float clamp01(float x) { return clamp(x, 0.0, 1.0); }
vec2 clamp01(vec2 x) { return clamp(x, vec2(0.0), vec2(1.0)); }
vec3 clamp01(vec3 x) { return clamp(x, vec3(0.0), vec3(1.0)); }
vec4 clamp01(vec4 x) { return clamp(x, vec4(0.0), vec4(1.0)); }
float lum(vec3 x) { return dot(x, vec3(0.32, 0.49, 0.29)); }
float lum(vec4 x) { return dot(x.rgb, vec3(0.32, 0.49, 0.29)); }
float sat(float x) { return clamp(x, 0.0, 1.0); }
vec2 sat(vec2 x) { return clamp(x, vec2(0.0), vec2(1.0)); }
vec3 sat(vec3 x) { return clamp(x, vec3(0.0), vec3(1.0)); }
vec4 sat(vec4 x) { return clamp(x, vec4(0.0), vec4(1.0)); }

vec3 GetPixel(vec2 uv) { return texture(sampler_main, uv).xyz; }
vec3 GetBlur1(vec2 uv) { return texture(sampler_blur1, uv).xyz; }
vec3 GetBlur2(vec2 uv) { return texture(sampler_blur2, uv).xyz; }
vec3 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv).xyz; }
vec4 noise3(vec2 uv) { return texture(sampler_noise_lq, uv); }
vec3 GetMain(vec2 uv) { return texture(sampler_main, uv).xyz; }
vec2 multiply(vec2 v, mat2 m) { return m * v; }
vec3 multiply(vec3 v, mat3 m) { return m * v; }
vec4 multiply(vec4 v, mat4 m) { return m * v; }
vec4 textureBias(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
vec4 textureLod4(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
vec3 reta;
vec3 retb;
vec3 retc;
shader_body
{
uv = 0.5 + (uv-0.5)*0.98;
vec2 d = (vec2(1.0)/uTexSize) * 4.0;
vec3 dx = ( GetBlur1(uv+vec2( 1.0 , 0.0 )*d)-GetBlur1(uv-vec2( 1.0 , 0.0 )*d).xy );
vec3 dy = ( GetBlur1(uv+vec2( 0.0 , 1.0 )*d)-GetBlur1(uv-vec2( 0.0 , 1.0 )*d).xy );
vec4 noise = tex3D(sampler_noisevol_hq, ((uv.xyy+vec3(lum(dx),lum(dy), 0.0 )*0.5)*uTexSize.xyy*texsize_noisevol_hq.zww).xyz*vec3( 1.0 , 1.0 , 0.0 )*0.05
+ uTime*vec3( 0.0 , 0.0 , 1.0 )*0.2 );
uv -= vec2(lum(dx),lum(dy))*0.04;
ret = abs(GetPixel(uv)+GetBlur1(uv).xy-GetBlur2(uv)-GetBlur3(uv));
ret *= lum(noise) * 3.0;
ret = pow(ret,0.5);
vec2 uv2 = uv*0.25;
vec3 col = 0;
vec2 uv3 = uv2;
for(int i = 0; i<16; i++){
uv3 += i*vec2(0.25, 0.0 ) - (0==(i)%4)*vec2( 0.0 ,0.25);
col = mix(col,i/16.0,clamp01(-GetPixel(uv3).y+tex2d(sampler_pw_main,fract(uv3)).y));
}
reta = mix(GetPixel(uv).z*vec3(0.6, 0.2, 1.0),vec3( 1.0 , 1.0 , 1.0),col*clamp01(1.0 - GetBlur1(uv).x * 2.0));
retb = mix(GetPixel(uv).z*vec3(0.6, 0.2, 1.0),vec3( 1.0 , 1.0 , 1.0),col*clamp01(1.0 - GetBlur1(uv).x * 2.0));
float gx = GetPixel(uv+vec2( 1.0 , 0.0 )*(vec2(1.0)/uTexSize)) - GetPixel(uv-vec2( 1.0 , 0.0 )*(vec2(1.0)/uTexSize));
float gy = GetPixel(uv+vec2( 0.0 , 1.0 )*(vec2(1.0)/uTexSize)) - GetPixel(uv-vec2( 0.0 , 1.0 )*(vec2(1.0)/uTexSize));
vec3 g = normalize(vec3(gx, gy, .04));
reta = mix(ret,vec3(1.1,0.8,0.5),(dot(g.xyz,vec3(fract(uv)-0.5,0.6))*0.5+0.5)*GetPixel(fract(uv)).x);
retb = mix(ret,vec3(1.1,0.8,0.5),(dot(g.xyz,vec3(fract(uv)-0.5,0.6))*0.5+0.5)*GetPixel(fract(uv)).x);
//retc = mix(ret,retb,(sin(uTime) * 100.0));
ret = mix(ret,reta,q20);
retc = mix(ret,retb,(sin(uTime) * 100.0));
ret = mix(ret,retc,q20);
ret = vec3( 1.0 ) - ret;
ret *= audioHighSmooth * .5;
}

